    public const string Icerik = """
<!doctype html>
<html lang="tr">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover">
<title>Yazılım Borsası v4.1</title>
<style>
:root{color-scheme:dark;--bg:#040711;--panel:#0a1322;--panel2:#101c30;--line:#21334d;--text:#eef5ff;--muted:#8da1bd;--green:#3de3a0;--blue:#5ca7ff;--red:#ff687b;--yellow:#ffd166;--purple:#b58cff;--cyan:#41d5ee;--shadow:0 18px 52px #0008}*{box-sizing:border-box}html{scroll-behavior:smooth}html,body{margin:0;min-height:100%;background:radial-gradient(circle at 8% 0,#10274a 0,transparent 34%),radial-gradient(circle at 92% 0,#25154c 0,transparent 30%),var(--bg);color:var(--text);font-family:Inter,Segoe UI,Arial,sans-serif}body{padding:12px}.shell{max-width:2100px;margin:auto}.top{display:flex;justify-content:space-between;align-items:center;gap:15px;padding:14px 16px;border:1px solid var(--line);border-radius:17px;background:#091322ec;box-shadow:var(--shadow);position:sticky;top:7px;z-index:30;backdrop-filter:blur(14px)}.brand{display:flex;align-items:center;gap:11px}.logo{width:45px;height:45px;border-radius:14px;background:linear-gradient(135deg,var(--green),var(--blue),var(--purple));display:grid;place-items:center;color:#03161b;font-weight:1000}.brand h1{margin:0;font-size:19px}.brand small{display:block;color:var(--muted);font-size:10px;margin-top:3px}.status{display:flex;gap:7px;flex-wrap:wrap;justify-content:flex-end}.pill{border:1px solid var(--line);border-radius:999px;background:#091525;padding:7px 10px;color:var(--muted);font-size:10px}.pill b{color:var(--text)}.dot{display:inline-block;width:8px;height:8px;border-radius:50%;background:var(--yellow);margin-right:6px}.dot.ok{background:var(--green);box-shadow:0 0 12px var(--green)}.dot.bad{background:var(--red)}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin:12px 0}.tab{cursor:pointer;border:1px solid var(--line);background:#091525;color:var(--muted);border-radius:999px;padding:8px 12px;font-weight:800}.tab.active{background:linear-gradient(135deg,var(--green),var(--blue));color:#03161b;border-color:transparent}.page{display:none}.page.active{display:block}.stack{display:grid;gap:12px}.card{background:linear-gradient(180deg,#101c30ec,#08101dec);border:1px solid var(--line);border-radius:15px;box-shadow:var(--shadow);overflow:hidden}.head{display:flex;justify-content:space-between;align-items:center;gap:10px;padding:12px 14px;border-bottom:1px solid var(--line)}.title{font-size:13px;font-weight:950;letter-spacing:.05em}.note{font-size:9px;color:var(--muted)}.kpis{display:grid;grid-template-columns:repeat(9,minmax(120px,1fr));gap:9px;margin-bottom:12px}.kpi{background:linear-gradient(180deg,#101d31,#091321);border:1px solid var(--line);border-radius:13px;padding:11px;min-height:88px;position:relative;overflow:hidden}.kpi:after{content:"";position:absolute;width:80px;height:80px;border-radius:50%;right:-35px;bottom:-45px;background:var(--a,var(--blue));filter:blur(30px);opacity:.25}.kpi span{display:block;color:var(--muted);font-size:9px;text-transform:uppercase;letter-spacing:.08em}.kpi b{display:block;margin-top:10px;font-size:19px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.company-grid{display:grid;grid-template-columns:repeat(4,minmax(275px,1fr));gap:9px;padding:10px}.company{background:#081321;border:1px solid var(--line);border-radius:13px;padding:12px;position:relative;overflow:hidden}.company:before{content:"";position:absolute;left:0;top:0;bottom:0;width:4px;background:var(--c,var(--blue))}.company-top{display:flex;justify-content:space-between;gap:8px}.company-name{font-size:16px;font-weight:950}.company-id{font-size:8px;color:var(--muted);margin-top:3px}.rank{font-size:20px;font-weight:1000;color:var(--yellow)}.state{display:inline-block;margin-top:5px;padding:3px 6px;border:1px solid #28634f;border-radius:999px;color:var(--green);font-size:8px}.state.off{border-color:#743746;color:var(--red)}.metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:9px}.metric{padding:7px;background:#0d192b;border:1px solid #1b2a42;border-radius:8px;min-width:0}.metric span{display:block;color:var(--muted);font-size:7px;text-transform:uppercase}.metric b{display:block;margin-top:3px;font-size:11px;overflow:hidden;text-overflow:ellipsis}.bars{display:grid;gap:5px;margin-top:8px}.barrow{display:grid;grid-template-columns:64px 1fr 30px;gap:5px;align-items:center;font-size:8px;color:var(--muted)}.bar{height:5px;border-radius:99px;background:#16243a;overflow:hidden}.bar i{display:block;height:100%;background:linear-gradient(90deg,var(--blue),var(--green))}.chips{display:flex;flex-wrap:wrap;gap:4px;margin-top:8px}.chip{font-size:7px;padding:3px 5px;border:1px solid #263850;border-radius:6px;color:#c0cee2}.chip.good{border-color:#28634f;color:var(--green)}.chip.bad{border-color:#743746;color:var(--red)}.tablewrap{overflow:auto;max-height:680px}table{width:100%;border-collapse:collapse;min-width:1000px;font-size:10px}th{position:sticky;top:0;background:#101c30;color:var(--muted);font-size:8px;text-transform:uppercase;letter-spacing:.07em;text-align:left;padding:9px;border-bottom:1px solid var(--line);z-index:2}td{padding:9px;border-bottom:1px solid #1b2a41;vertical-align:top}tr:hover td{background:#5ca7ff09}.num{text-align:right;font-variant-numeric:tabular-nums}.good{color:var(--green)}.bad{color:var(--red)}.warn{color:var(--yellow)}.muted{color:var(--muted)}.name{font-weight:900}.small{font-size:8px;color:var(--muted);margin-top:3px}.progress{height:6px;background:#152239;border-radius:99px;overflow:hidden;min-width:90px}.progress i{display:block;height:100%;background:linear-gradient(90deg,var(--purple),var(--cyan))}.two{display:grid;grid-template-columns:1fr 1fr;gap:12px}.summary{display:grid;grid-template-columns:repeat(5,1fr);gap:7px;padding:10px}.summary .metric{padding:9px}.log{height:540px;overflow:auto;padding:8px 10px;background:#050a12;font:9px/1.45 Consolas,monospace}.logline{display:grid;grid-template-columns:58px 62px 1fr;gap:6px;border-bottom:1px dashed #18253a;padding:4px 0}.level{font-weight:850}.level.HATA{color:var(--red)}.level.UYARI{color:var(--yellow)}.level.BASARILI{color:var(--green)}.level.TICK{color:var(--purple)}.level.BILGI{color:var(--cyan)}.empty{padding:22px;text-align:center;color:var(--muted)}.home-section{scroll-margin-top:90px}.home-section .tablewrap{max-height:440px}.home-divider{height:1px;background:linear-gradient(90deg,transparent,var(--line),transparent);margin:3px 0}.footer{text-align:center;color:var(--muted);font-size:8px;padding:13px}@media(max-width:1650px){.kpis{grid-template-columns:repeat(5,1fr)}.company-grid{grid-template-columns:repeat(3,1fr)}}@media(max-width:1200px){.company-grid{grid-template-columns:repeat(2,1fr)}.two{grid-template-columns:1fr}}@media(max-width:760px){body{padding:6px}.top{position:static;align-items:flex-start;flex-direction:column}.status{justify-content:flex-start}.kpis{grid-template-columns:repeat(2,1fr)}.company-grid{grid-template-columns:1fr}.summary{grid-template-columns:repeat(2,1fr)}}
</style>
</head>
<body>
<div class="shell"><header class="top"><div class="brand"><div class="logo">YB</div><div><h1>Yazılım Borsası v4.1</h1><small>Şirket değeri · ürünler · aboneler · protokoller · kapasite · finans · güvenlik</small></div></div><div class="status"><span class="pill"><i id="dot" class="dot"></i><b id="connection">BAĞLANIYOR</b></span><span class="pill">Motor <b id="motor">—</b></span><span class="pill">Tick <b id="tick">0</b></span><span class="pill">Gecikme <b id="latency">—</b></span><span class="pill" id="clock">—</span></div></header><nav class="tabs"><button class="tab active" data-page="home">Ana Sayfa</button><button class="tab" data-page="overview">Genel Borsa</button><button class="tab" data-page="apps">Uygulamalar</button><button class="tab" data-page="protocols">Protokoller</button><button class="tab" data-page="services">Hizmetler</button><button class="tab" data-page="finance">Finans & Banka</button><button class="tab" data-page="operations">Sözleşmeler & Yatırımlar</button><button class="tab" data-page="security">Güvenlik & Akış</button></nav><section id="kpis" class="kpis"></section><main id="home" class="page active stack"></main><main id="overview" class="page stack"></main><main id="apps" class="page stack"></main><main id="protocols" class="page stack"></main><main id="services" class="page stack"></main><main id="finance" class="page stack"></main><main id="operations" class="page stack"></main><main id="security" class="page stack"></main><div class="footer">8080 salt-okunur piyasa ekranıdır · Yönetim işlemleri 8090 üzerinden yapılır</div></div>
<script>
const S={data:null,loading:false,started:performance.now(),colors:['#3de3a0','#5ca7ff','#b58cff','#ffd166','#41d5ee','#ff687b']};const money=new Intl.NumberFormat('tr-TR',{style:'currency',currency:'TRY',maximumFractionDigits:2}),num=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:2}),integer=new Intl.NumberFormat('tr-TR',{maximumFractionDigits:0});const m=v=>money.format(Number(v||0)),n=v=>num.format(Number(v||0)),i=v=>integer.format(Number(v||0)),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const chip=(v,cls='')=>`<span class="chip ${cls}">${esc(v)}</span>`;const metric=(l,v,cls='')=>`<div class="metric"><span>${esc(l)}</span><b class="${cls}">${esc(v)}</b></div>`;function bar(l,v){const x=Math.max(0,Math.min(100,Number(v||0)));return `<div class="barrow"><span>${esc(l)}</span><div class="bar"><i style="width:${x}%"></i></div><b>${n(x)}</b></div>`}
function companyValue(c){const s=c||{},o=s.isletim||{},k=s.kodTabanliYayinlar||{},products=o.urunler||[],services=k.hizmetler||s.hizmetler||[],protocols=k.protokoller||[],contracts=o.sozlesmeler||[],invest=Object.values(o.yatirimSeviyeleri||{}).reduce((a,b)=>a+Number(b||0),0),users=products.reduce((a,p)=>a+Number(p.aktifKullaniciSayisi||0),0),capacity=products.reduce((a,p)=>a+Number(p.kullaniciKapasitesi||0),0)+services.reduce((a,h)=>a+Number(h.azamiEszamanliIs||0),0)*50,productProfit=products.reduce((a,p)=>a+Math.max(0,Number(p.toplamGelir||0)-Number(p.toplamGider||0)),0),history=Number(s.tamamlananIsSayisi||0)*30+Math.max(0,Number(s.netGelir||0))*0.08,quality=(Number(s.kodKalitesiPuani||0)+Number(s.performansPuani||0)+Number(s.guvenlikPuani||0)+Number(s.itibarPuani||0)+Number(s.guvenilirlikPuani||0)+Number(s.ortalamaMusteriMemnuniyeti||0))*180,ecosystem=Number(o.ekosistemPuani||0)*300+protocols.filter(p=>p.piyasada).length*9000+services.filter(h=>h.aktif).length*1200,contractsValue=contracts.reduce((a,x)=>a+(x.aktif?Number(x.tickOdemesi||0)*Math.max(1,Number(x.bitisTicki||0)-Number(S.data?.motor?.tickNumarasi||0)):Number(x.basariliTickSayisi||0)*80)-Number(x.ihlalSayisi||0)*500,0),cash=Math.max(0,Number(s.kasa||0))*0.15,debt=Number(o.toplamBorc||0)*1.15+Number(o.odenemeyenGider||0)*1.5+Number(o.temerrutSayisi||0)*5000;return Math.max(0,cash+users*55+capacity*4+productProfit*7+history+quality+ecosystem+contractsValue+invest*3500-debt)}
function values(data){return (data.sirketler||[]).map(c=>({...c,hesaplananDeger:companyValue(c)})).sort((a,b)=>b.hesaplananDeger-a.hesaplananDeger)}
function kpis(data,companies){const g=data.genel||{},apps=data.uygulamaPiyasasi||[],protocols=data.protokolPiyasasi||[],totalValue=companies.reduce((a,c)=>a+c.hesaplananDeger,0),totalSubs=companies.reduce((a,c)=>a+Number(c.isletim?.toplamAboneSayisi||0),0),totalCapacity=companies.reduce((a,c)=>a+(c.isletim?.urunler||[]).reduce((x,p)=>x+Number(p.kullaniciKapasitesi||0),0),0);document.getElementById('kpis').innerHTML=[['Toplam şirket değeri',m(totalValue),'var(--purple)'],['Toplam kasa',m(g.toplamSirketKasasi),'var(--green)'],['Toplam borç',m(g.toplamBorc),'var(--red)'],['Aktif abone',i(totalSubs),'var(--cyan)'],['Ürün kapasitesi',i(totalCapacity),'var(--blue)'],['Uygulamalar',`${i(apps.filter(x=>x.piyasada).length)} / ${i(apps.length)}`,'var(--blue)'],['Protokoller',`${i(protocols.filter(x=>x.piyasada).length)} / ${i(protocols.length)}`,'var(--yellow)'],['Bağlı şirket',`${i(g.bagliSirketSayisi)} / ${i(g.toplamSirketSayisi)}`,'var(--green)'],['Siber olay',`${i(g.toplamEngellenenSaldiri)} / ${i(g.toplamBasariliSaldiri)}`,'var(--red)']].map(x=>`<div class="kpi" style="--a:${x[2]}"><span>${x[0]}</span><b>${x[1]}</b></div>`).join('')}
function companiesSection(companies,title='ŞİRKET DEĞER LİSTESİ'){return `<section class="card home-section"><div class="head"><div><div class="title">${title}</div><div class="note">Değer; geçmiş, ürün, kullanıcı, kapasite, hizmet, protokol, SLA, kalite ve borç riskinden hesaplanır. Kasa yalnız %15 likidite ağırlığı taşır.</div></div></div><div class="company-grid">${companies.map((c,index)=>{const o=c.isletim||{},apps=c.kodTabanliYayinlar?.uygulamalar||[],protocols=c.kodTabanliYayinlar?.protokoller||[],invest=Object.entries(o.yatirimSeviyeleri||{}).filter(([,v])=>Number(v)>0);return `<article class="company" style="--c:${S.colors[index%S.colors.length]}"><div class="company-top"><div><div class="company-name">${esc(c.sirketAdi)}</div><div class="company-id">${esc(c.sirketKimligi)} · ${esc(c.sunucuAdresi)}:${esc(c.sunucuPortu)} · v${esc(c.sunucuSurumu||'—')}</div><span class="state ${c.bagli?'':'off'}">${c.bagli?'BAĞLI':'ÇEVRİMDIŞI'}</span></div><div class="rank">#${index+1}</div></div><div class="metrics">${metric('Şirket değeri',m(c.hesaplananDeger),'good')}${metric('Hisse tahmini',m(c.hesaplananDeger/10000))}${metric('Kasa',m(c.kasa))}${metric('Borç',m(o.toplamBorc),Number(o.toplamBorc)>0?'warn':'')}${metric('Abone',i(o.toplamAboneSayisi))}${metric('Hizmet',i((c.kodTabanliYayinlar?.hizmetler||c.hizmetler||[]).length))}${metric('Uygulama',`${apps.filter(x=>x.piyasada).length}/${apps.length}`)}${metric('Protokol',`${protocols.filter(x=>x.piyasada).length}/${protocols.length}`)}${metric('Gecikme',`${n(c.sonGecikmeMs)} ms`)}</div><div class="bars">${bar('Kod',c.kodKalitesiPuani)}${bar('Performans',c.performansPuani)}${bar('Güvenlik',c.guvenlikPuani)}${bar('İtibar',c.itibarPuani)}${bar('Güvenilir',c.guvenilirlikPuani)}${bar('Memnuniyet',c.ortalamaMusteriMemnuniyeti)}</div><div class="chips">${apps.map(x=>chip(`${x.uygulama?.uygulamaAdi||x.uygulama?.uygulamaKimligi} ${x.piyasada?'●':'○'}`,x.piyasada?'good':'')).join('')}${protocols.map(x=>chip(`${x.protokol?.protokolAdi||x.protokol?.protokolKimligi} ${x.piyasada?'●':'○'}`,x.piyasada?'good':'')).join('')}${invest.map(([k,v])=>chip(`${k} L${v}`)).join('')}</div></article>`}).join('')||'<div class="empty">Şirket yok.</div>'}</div></section>`}
function appsSection(data){const list=data.uygulamaPiyasasi||[];return `<section class="card home-section"><div class="head"><div><div class="title">UYGULAMA VE ABONELİK PAZARI</div><div class="note">Teknik manifest, ticari yayın, fiyat, kullanıcı, kapasite, kalite ve gelir</div></div></div><div class="tablewrap"><table><thead><tr><th>Uygulama</th><th>Şirket</th><th>Kategori</th><th>Teknik</th><th>Ticari</th><th>Model</th><th class="num">Abonelik</th><th class="num">Kullanım</th><th>Kullanıcı / Kapasite</th><th class="num">Kalite</th><th class="num">Memnuniyet</th><th class="num">Gelir</th></tr></thead><tbody>${list.map(a=>{const app=a.uygulama||{},d=a.dogrulama||{},u=a.urun||{},users=Number(u.aktifKullaniciSayisi||0),cap=Number(u.kullaniciKapasitesi||0),ratio=cap?Math.min(100,users/cap*100):0;return `<tr><td><div class="name">${esc(app.uygulamaAdi||app.uygulamaKimligi)}</div><div class="small">${esc(app.uygulamaKimligi)} · v${esc(app.surum||'—')} · ${(app.ozellikler||[]).length} özellik</div></td><td>${esc(a.sirketAdi)}</td><td>${esc(app.kategori||'—')}</td><td class="${d.gecerli?'good':'bad'}">${d.gecerli?'STANDARDI GEÇTİ':'EKSİK'}</td><td class="${a.piyasada?'good':'muted'}">${a.piyasada?(u.aktif?'YAYINDA':'DURDURULDU'):'8090 BEKLİYOR'}</td><td>${esc(u.fiyatlandirmaModeli||'—')}</td><td class="num">${a.piyasada?m(u.abonelikUcreti):'—'}</td><td class="num">${a.piyasada?m(u.kullanimBasinaUcret):'—'}</td><td><div>${i(users)} / ${i(cap)}</div><div class="progress"><i style="width:${ratio}%"></i></div></td><td class="num">${a.piyasada?n(u.urunKalitesi):'—'}</td><td class="num">${a.piyasada?n(u.urunMemnuniyeti):'—'}</td><td class="num good">${a.piyasada?m(u.toplamGelir):'—'}</td></tr>`}).join('')||'<tr><td colspan="12" class="empty">Kodlanmış uygulama yok.</td></tr>'}</tbody></table></div></section>`}
function protocolsSection(data){const list=data.protokolPiyasasi||[];return `<section class="card home-section"><div class="head"><div><div class="title">ÖZEL PROTOKOL PİYASASI</div><div class="note">Kodlanmış yetkinlik, şema, uyumluluk ve ticari lisans durumu</div></div></div><div class="tablewrap"><table><thead><tr><th>Protokol</th><th>Sahip</th><th>Sürüm</th><th>Şema</th><th>Teknik</th><th>Ticari</th><th>Yetkinlikler</th><th>Uyumluluk</th></tr></thead><tbody>${list.map(x=>{const p=x.teknikProtokol||{};return `<tr><td><div class="name">${esc(p.protokolAdi||p.protokolKimligi)}</div><div class="small">${esc(p.protokolKimligi)}</div></td><td>${esc(x.sirketAdi)}</td><td>${esc(p.surum||'—')}</td><td><div>${esc(p.semaKimligi||'—')}</div><div class="small">${esc(p.semaOzeti||'')}</div></td><td class="${x.gecerli?'good':'bad'}">${x.gecerli?'GEÇERLİ':'EKSİK'}</td><td class="${x.piyasada?'good':'muted'}">${x.piyasada?'LİSANSLANABİLİR':'8090 BEKLİYOR'}</td><td>${(p.yetkinlikler||[]).map(y=>chip(`${y.yetkinlikKimligi} → ${y.hizmetKimligi}`)).join('')}</td><td>${(p.uyumluProtokoller||[]).map(y=>chip(y)).join('')||'—'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Özel protokol yok.</td></tr>'}</tbody></table></div></section>`}
function servicesSection(data){const list=data.hizmetPiyasasi||[];return `<section class="card home-section"><div class="head"><div><div class="title">TEMEL HİZMET PİYASASI</div><div class="note">Talep, bütçe, fiyat aralığı ve aktif sağlayıcılar</div></div></div><div class="tablewrap"><table><thead><tr><th>Hizmet</th><th class="num">Talep</th><th class="num">Şüpheli</th><th class="num">Zorluk</th><th class="num">Bütçe</th><th class="num">En ucuz</th><th class="num">En pahalı</th><th>Sağlayıcılar</th></tr></thead><tbody>${list.map(s=>`<tr><td><div class="name">${esc(s.hizmetKimligi)}</div><div class="small">v${esc(s.hizmetSurumu)}</div></td><td class="num">${i(s.talepSayisi)}</td><td class="num ${Number(s.kotuNiyetliTalepSayisi)>0?'bad':''}">${i(s.kotuNiyetliTalepSayisi)}</td><td class="num">${n(s.ortalamaZorlukSeviyesi)}</td><td class="num">${m(s.toplamTalepButcesi)}</td><td class="num good">${s.enUcuzFiyat==null?'—':m(s.enUcuzFiyat)}</td><td class="num">${s.enPahaliFiyat==null?'—':m(s.enPahaliFiyat)}</td><td>${(s.saglayicilar||[]).map(x=>chip(`${x.sirketAdi} ${m(x.birimFiyat)} · K${n(x.kodKalitesiPuani)} P${n(x.performansPuani)} G${n(x.guvenlikPuani)}`,x.bagli?'good':'bad')).join('')||'<span class="bad">Sağlayıcı yok</span>'}</td></tr>`).join('')||'<tr><td colspan="8" class="empty">Hizmet piyasası boş.</td></tr>'}</tbody></table></div></section>`}
function financeSection(data,companies){const credits=(data.krediPiyasasi||[]).filter(x=>x.kredi);return `<section class="card home-section"><div class="head"><div><div class="title">FİNANS VE ŞİRKET DEĞERLEMESİ</div><div class="note">Kasa dışı ekonomik varlıklar şirket değerinin ana bölümüdür</div></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th class="num">Değer</th><th class="num">Hisse</th><th class="num">Kasa</th><th class="num">Borç</th><th class="num">Kredi notu</th><th class="num">Abone</th><th class="num">Ürün geliri</th><th class="num">Gider</th></tr></thead><tbody>${companies.map(c=>{const o=c.isletim||{};return `<tr><td class="name">${esc(c.sirketAdi)}</td><td class="num good">${m(c.hesaplananDeger)}</td><td class="num">${m(c.hesaplananDeger/10000)}</td><td class="num">${m(c.kasa)}</td><td class="num ${Number(o.toplamBorc)>0?'warn':''}">${m(o.toplamBorc)}</td><td class="num">${i(o.krediNotu)}</td><td class="num">${i(o.toplamAboneSayisi)}</td><td class="num good">${m(o.toplamUrunGeliri)}</td><td class="num bad">${m(Number(o.toplamIsletmeGideri||0)+Number(o.toplamFinansmanGideri||0))}</td></tr>`}).join('')}</tbody></table></div></section><section class="card home-section"><div class="head"><div class="title">AKTİF KREDİLER</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Tür</th><th class="num">Ana para</th><th class="num">Kalan</th><th class="num">Taksit</th><th class="num">Kalan taksit</th><th class="num">Gecikme</th><th>Durum</th></tr></thead><tbody>${credits.map(x=>{const k=x.kredi;return `<tr><td>${esc(x.sirketAdi)}</td><td>${esc(k.krediTuru)}</td><td class="num">${m(k.anaPara)}</td><td class="num warn">${m(k.kalanBorc)}</td><td class="num">${m(k.taksitTutari)}</td><td class="num">${i(k.kalanTaksit)}</td><td class="num ${Number(k.gecikmeSayisi)>0?'bad':''}">${i(k.gecikmeSayisi)}</td><td class="${k.aktif?'warn':'good'}">${k.aktif?'AKTİF':'KAPANDI'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Kredi kaydı yok.</td></tr>'}</tbody></table></div></section>`}
function operationsSection(data){const contracts=data.sozlesmePiyasasi||[],invest=data.yatirimPiyasasi||[];return `<section class="card home-section"><div class="head"><div class="title">SLA SÖZLEŞMELERİ</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Sözleşme</th><th>Kategori</th><th>Dönem</th><th class="num">Ödeme</th><th class="num">Başarı</th><th class="num">İhlal</th><th>Durum</th></tr></thead><tbody>${contracts.map(x=>{const s=x.sozlesme;return `<tr><td>${esc(x.sirketAdi)}</td><td class="name">${esc(s.baslik)}</td><td>${esc(s.kategori)}</td><td>${i(s.baslangicTicki)}–${i(s.bitisTicki)}</td><td class="num good">${m(s.tickOdemesi)}</td><td class="num good">${i(s.basariliTickSayisi)}</td><td class="num ${Number(s.ihlalSayisi)>0?'bad':''}">${i(s.ihlalSayisi)}</td><td class="${s.aktif?'good':'muted'}">${s.aktif?'AKTİF':'BİTTİ'}</td></tr>`}).join('')||'<tr><td colspan="8" class="empty">Sözleşme yok.</td></tr>'}</tbody></table></div></section><section class="card home-section"><div class="head"><div class="title">YATIRIM SEVİYELERİ</div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th>Yatırım</th><th class="num">Seviye</th></tr></thead><tbody>${invest.filter(x=>Number(x.seviye)>0).map(x=>`<tr><td>${esc(x.sirketAdi)}</td><td>${esc(x.yatirimTuru)}</td><td class="num good">${i(x.seviye)}</td></tr>`).join('')||'<tr><td colspan="3" class="empty">Henüz yatırım yok.</td></tr>'}</tbody></table></div></section>`}
function securitySection(data,companies){const logs=data.olaylar||[],o=data.piyasa?.islemeOzeti||{};return `<section class="card home-section"><div class="head"><div><div class="title">GÜVENLİK SIRALAMASI</div><div class="note">Engellenen saldırılar, başarılı saldırılar ve ekonomik kayıp</div></div></div><div class="tablewrap"><table><thead><tr><th>Şirket</th><th class="num">Güvenlik</th><th class="num">Kod</th><th class="num">Engellenen</th><th class="num">Başarılı saldırı</th><th class="num">Kayıp</th><th>Risk</th></tr></thead><tbody>${[...companies].sort((a,b)=>Number(b.guvenlikPuani)-Number(a.guvenlikPuani)).map(c=>{const risk=Number(c.guvenlikPuani)>=80?'DÜŞÜK':Number(c.guvenlikPuani)>=55?'ORTA':'YÜKSEK';return `<tr><td class="name">${esc(c.sirketAdi)}</td><td class="num ${risk==='DÜŞÜK'?'good':risk==='YÜKSEK'?'bad':'warn'}">${n(c.guvenlikPuani)}</td><td class="num">${n(c.kodKalitesiPuani)}</td><td class="num good">${i(c.engellenenSaldiriSayisi)}</td><td class="num ${Number(c.basariliSaldiriSayisi)>0?'bad':''}">${i(c.basariliSaldiriSayisi)}</td><td class="num bad">${m(c.toplamGuvenlikKaybi)}</td><td class="${risk==='DÜŞÜK'?'good':risk==='YÜKSEK'?'bad':'warn'}">${risk}</td></tr>`}).join('')}</tbody></table></div></section><div class="two"><section class="card home-section"><div class="head"><div class="title">SON TICK ÖZETİ</div></div><div class="summary">${metric('Talep',i(o.toplamTalepSayisi))}${metric('Başarılı',i(o.basariliIsSayisi),'good')}${metric('Başarısız',i(o.basarisizIsSayisi),Number(o.basarisizIsSayisi)>0?'bad':'')}${metric('Şüpheli',i(o.kotuNiyetliIsSayisi),Number(o.kotuNiyetliIsSayisi)>0?'warn':'')}${metric('Ciro',m(o.toplamCiro),'good')}${metric('Engellenen',i(o.engellenenSaldiriSayisi),'good')}${metric('Saldırı başarılı',i(o.basariliSaldiriSayisi),Number(o.basariliSaldiriSayisi)>0?'bad':'')}${metric('Zaman aşımı',i(o.zamanAsimiSayisi),Number(o.zamanAsimiSayisi)>0?'bad':'')}${metric('Başarı',`${n(o.basariOrani)}%`)}</div></section><section class="card home-section"><div class="head"><div class="title">CANLI MOTOR AKIŞI</div></div><div id="log" class="log">${logs.map(x=>`<div class="logline"><span class="muted">${new Date(x.zaman).toLocaleTimeString('tr-TR')}</span><span class="level ${esc(x.seviye)}">${esc(x.seviye)}</span><span>${esc(x.mesaj)}</span></div>`).join('')||'<div class="empty">Motor olayı yok.</div>'}</div></section></div>`}
function render(data){S.data=data;const companies=values(data);kpis(data,companies);const c=companiesSection(companies),a=appsSection(data),p=protocolsSection(data),s=servicesSection(data),f=financeSection(data,companies),o=operationsSection(data),g=securitySection(data,companies);document.getElementById('home').innerHTML=`${c}<div class="home-divider"></div>${a}<div class="home-divider"></div>${p}<div class="home-divider"></div>${s}<div class="home-divider"></div>${f}<div class="home-divider"></div>${o}<div class="home-divider"></div>${g}`;document.getElementById('overview').innerHTML=c;document.getElementById('apps').innerHTML=a;document.getElementById('protocols').innerHTML=p;document.getElementById('services').innerHTML=s;document.getElementById('finance').innerHTML=f;document.getElementById('operations').innerHTML=o;document.getElementById('security').innerHTML=g;const log=document.querySelector('#security #log');if(log)log.scrollTop=log.scrollHeight}
async function refresh(){if(S.loading)return;S.loading=true;const started=performance.now();try{const r=await fetch(`/api/durum?t=${Date.now()}`,{cache:'no-store'});if(!r.ok)throw new Error(`HTTP ${r.status}`);const data=await r.json();render(data);document.getElementById('dot').className='dot ok';document.getElementById('connection').textContent='CANLI';document.getElementById('motor').textContent=data.motor?.motorKimligi||'—';document.getElementById('tick').textContent=data.motor?.tickNumarasi??0;document.getElementById('latency').textContent=`${Math.round(performance.now()-started)} ms`}catch(e){document.getElementById('dot').className='dot bad';document.getElementById('connection').textContent='BAĞLANTI YOK';console.error(e)}finally{S.loading=false}}
document.querySelectorAll('.tab').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('.tab').forEach(x=>x.classList.remove('active'));document.querySelectorAll('.page').forEach(x=>x.classList.remove('active'));button.classList.add('active');document.getElementById(button.dataset.page).classList.add('active');window.scrollTo({top:0,behavior:'smooth'})}));setInterval(()=>document.getElementById('clock').textContent=new Date().toLocaleTimeString('tr-TR'),250);setInterval(refresh,450);refresh();
</script>
</body>
</html>
""";
}
